<script>document.addEventListener('DOMContentLoaded',()=>{const p=document.querySelectorAll('[data-panel]'),t=document.querySelectorAll('[data-tab]');const a=n=>{n=n||'overview';p.forEach(x=>x.classList.toggle('hidden',x.dataset.panel!==n));t.forEach(x=>x.classList.toggle('bg-white/10',x.dataset.tab===n));};t.forEach(x=>x.addEventListener('click',e=>{e.preventDefault();a(x.dataset.tab);history.replaceState(null,'','#'+x.dataset.tab);}));a(location.hash.replace('#','')||'overview');});</script></body></html>
